mapper.select:
SELECT * FROM chat_message 
WHERE room_id = #{roomId}
ORDER BY created_at ASC

SELECT COUNT(cm.id) FROM chat_message cm
JOIN chat_room cr ON cm.room_id = cr.id
WHERE cm.room_id = #{chatRoomId}
  AND cm.sender_id != #{userId}
  AND ((cr.owner_id = #{userId} AND cm.read_by_owner = false) OR
       (cr.buyer_id = #{userId} AND cm.read_by_buyer = false))
